  const { pending } = useformstatus();
  return <button disabled={pending}>保存</button>;
}
export function nameform({ save }) {
  const [name, setname] = usestate('');
  const [state, submit] = useactionstate(async (_, formdata) => {
    const value = string(formdata.get('name') ?? '').trim();
    if (!value) return { error: '请输入名称', savedname: '' };
    const savedname = await save(value);
    return { error: '', savedname };
  }, { error: '', savedname: '' });
  return <form action={submit}>
    <label>名称<input name="name" value={name}
      onchange={e => setname(e.target.value)} /></label>
    <submit />
    <p role="status">{state.error || state.savedname}</p>
  </form>;
